<script setup lang="ts">
import { computed, ref } from 'vue'
import { Capacitor } from '@capacitor/core'
import { CloudUpload } from '@lucide/vue'
import { useAppStore } from '@/stores/app-store'
import { resolveBackupReminderThreshold } from '@/domain/models/settings'
import { countTransactionsSinceLastBackup, exportCsv } from '@/domain/services/backup'
import { createBackupFileName, saveBackupFile, shareTextFile } from '@/infrastructure/files/backup-file-service'

const store = useAppStore()

// 自上次备份以来新增 / 修改的流水数量；用户清掉设置里 lastBackupAt 后归零
const unbackedCount = computed(() => countTransactionsSinceLastBackup(store.transactions, store.settings.lastBackupAt))
const threshold = computed(() => resolveBackupReminderThreshold(store.settings.backupReminderThreshold))

const visible = computed(() => store.settings.backupReminderEnabled !== false && unbackedCount.value >= threshold.value)
const busy = ref(false)

async function quickBackup(): Promise<void> {
  if (busy.value) return
  busy.value = true
  try {
    const snapshot = await store.repository.exportSnapshot()
    const text = exportCsv(snapshot)
    const name = createBackupFileName()
    if (Capacitor.isNativePlatform()) {
      // 安卓 App：直接存到「下载」文件夹，不弹分享面板
      await saveBackupFile(text, 'csv', name)
    } else {
      // 网页版：走分享面板（可“存储到文件”保存），与「备份并分享」一致分享同一 CSV
      const result = await shareTextFile(name, text, 'text/csv;charset=utf-8')
      if (result === 'cancelled') {
        store.notify('分享已取消', 'info')
        return
      }
    }
    // 只有文件真正交到用户手里才记备份时间并提示成功；分享失败/取消均不误报（2026-09-27 终审修复）
    const stampedAt = new Date().toISOString()
    await store.repository.putSettings({ ...store.settings, lastBackupAt: stampedAt })
    store.settings = { ...store.settings, lastBackupAt: stampedAt }
    store.notify(Capacitor.isNativePlatform() ? `已备份到手机「下载」文件夹（Download/${name}）` : '备份完成，请将文件保存到安全位置', 'success')
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '备份失败', 'error')
  } finally {
    busy.value = false
  }
}
</script>

<template>
  <section v-if="visible" class="backup-banner" role="status" aria-live="polite">
    <span class="banner-icon"><CloudUpload :size="20" aria-hidden="true" /></span>
    <p class="banner-text">
      您有 <strong>{{ unbackedCount }}</strong> 笔流水未备份
      <span class="banner-hint">（阈值 {{ threshold }}）{{ '，' }}为避免丢失请尽快备份</span>
    </p>
    <button class="banner-action" type="button" :disabled="busy" @click="quickBackup">
      <CloudUpload :size="16" />{{ busy ? '备份中' : '一键备份' }}
    </button>
  </section>
</template>

