<script setup lang="ts">
import { computed, nextTick, onMounted } from 'vue'
import { CalendarDays, ChevronRight, PiggyBank, TrendingDown, TrendingUp } from '@lucide/vue'
import { useRouter } from 'vue-router'
import { buildDashboard, type CategoryTotal } from '@/domain/services/statistics'
import { formatCents } from '@/domain/services/money'
import { localDateKey, rangeBounds } from '@/domain/services/date-range'
import { useAppStore } from '@/stores/app-store'
import { consumeDrilldownReturnState, saveDrilldownReturnState } from '@/app/drilldown-return-state'
import { currentWindowScrollTop } from '@/app/scroll-position'
import BackupReminderBanner from '@/features/home/BackupReminderBanner.vue'
import IncomeExpenseChart from '@/features/reports/IncomeExpenseChart.vue'
import CategoryDistribution from '@/features/reports/CategoryDistribution.vue'

const store = useAppStore()
const router = useRouter()
// 从分类流水直接返回时恢复点击前滚动位置（一次性消费，底部导航重进不恢复）
const restoredDrilldownState = consumeDrilldownReturnState()
const stats = computed(() => buildDashboard(store.transactions, store.categories, new Date()))
/** 本月分类支出排行按二级分类聚合（PRD 5.1.1），与 buildDashboard 的 monthExpenseCategories 同口径 */
const monthExpenseGroups = computed(() => stats.value.monthExpenseCategories)
const summaryRows = computed(() => [
  { label: '今日', range: 'day', summary: stats.value.day },
  { label: '本月', range: 'month', summary: stats.value.month },
  { label: '本年', range: 'year', summary: stats.value.year },
])
onMounted(() => {
  store.initialize()
  void restoreDrilldownScrollPosition()
})

/** 下钻返回后的滚动恢复：等渲染与布局完成再无动画回原位（与流水/报表页恢复惯例一致）。 */
async function restoreDrilldownScrollPosition(): Promise<void> {
  const scrollTop = restoredDrilldownState?.source === 'home' ? restoredDrilldownState.scrollTop : undefined
  if (scrollTop === undefined) return
  await nextTick()
  requestAnimationFrame(() => {
    window.scrollTo({ top: scrollTop, left: 0, behavior: 'auto' })
  })
}

/** 点击排行行 → 该二级分类当前自然月的支出明细（复用报表二级流水页，见下钻返回状态设计）。 */
function openCategoryDetail(item: CategoryTotal): void {
  saveDrilldownReturnState({ source: 'home', scrollTop: currentWindowScrollTop() })
  const now = new Date()
  const bounds = rangeBounds('month', now)
  const endInclusive = new Date(bounds.endExclusive.getTime() - 1)
  void router.push({
    name: 'report-transactions',
    query: {
      dimension: 'category',
      level: 'child',
      focus: item.categoryId,
      type: 'expense',
      from: localDateKey(bounds.start),
      to: localDateKey(endInclusive),
    },
  })
}
</script>

<template>
  <main class="page home-page">
    <BackupReminderBanner />
    <section class="balance-card">
      <div class="balance-title"><TrendingDown :size="20" aria-hidden="true" /><span>本月支出</span></div>
      <strong class="balance money">{{ formatCents(stats.month.expenseCents) }}</strong>
      <div class="balance-grid">
        <div><span><TrendingUp :size="17" />本月收入</span><strong class="income money">{{ formatCents(stats.month.incomeCents) }}</strong></div>
        <div><span><PiggyBank :size="17" />本月结余</span><strong class="money">{{ formatCents(stats.month.balanceCents) }}</strong></div>
      </div>
    </section>

    <section class="card summary-card" aria-labelledby="summary-title">
      <h2 id="summary-title"><CalendarDays :size="20" aria-hidden="true" />收支概览</h2>
      <button v-for="row in summaryRows" :key="row.range" type="button" @click="router.push({ name: 'transactions', query: { range: row.range } })">
        <strong>{{ row.label }}</strong>
        <span class="summary-values">
          <span class="income">收 {{ formatCents(row.summary.incomeCents) }}</span>
          <span class="expense">支 {{ formatCents(row.summary.expenseCents) }}</span>
        </span>
        <ChevronRight :size="19" aria-hidden="true" />
      </button>
    </section>

    <section class="card chart-card">
      <h2>本月收支趋势</h2>
      <p>按日期查看收入和支出变化</p>
      <IncomeExpenseChart :points="stats.monthDailyTrend" :initial-active-key="stats.monthDailyTrend.at(-1)?.key" title="本月收支趋势" />
    </section>

    <section class="card category-card">
      <h2>本月分类支出排行</h2>
      <p>{{ stats.month.expenseCents ? `本月累计支出 ${formatCents(stats.month.expenseCents)}` : '本月暂无支出记录' }}</p>
      <CategoryDistribution :items="monthExpenseGroups" :all-categories="store.categories" clickable empty-text="记一笔支出后，这里会显示分类分布" @select="openCategoryDetail" />
    </section>
  </main>
</template>

